css:
.bs { max-width: 1200px; margin-inline: auto; }
.bs__head { margin-bottom: var(--os-space-xl); }
.bs__eyebrow { margin: 0 0 var(--os-space-xs); font-family: var(--os-font-label); font-size: var(--os-type-eyebrow-font-size); letter-spacing: var(--os-type-eyebrow-letter-spacing); text-transform: uppercase; color: var(--os-eyebrow-color, var(--os-color-accent)); }
.bs__title { margin: 0; font-family: var(--os-font-heading); font-weight: var(--os-font-weight-heading); font-size: var(--os-type-h1-font-size); line-height: var(--os-type-h1-line-height); color: var(--os-color-heading); text-wrap: balance; max-width: 18em; }
.bs__grid { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--os-space-md); }
.bs__card { position: relative; background: var(--os-color-surface); border: 2px solid var(--os-color-heading); border-radius: var(--os-radius-image, 14px); padding: var(--os-space-lg); box-shadow: 6px 6px 0 var(--os-color-heading); }
.bs__dots { display: flex; gap: 6px; margin-bottom: var(--os-space-sm); min-height: 22px; }
.bs__dot { width: 22px; height: 22px; border-radius: 50%; background: var(--os-color-accent); border: 2px solid var(--os-color-heading); }
.bs__name { margin: 0 0 var(--os-space-2xs); font-family: var(--os-font-label); font-size: var(--os-type-eyebrow-font-size); letter-spacing: var(--os-type-eyebrow-letter-spacing); text-transform: uppercase; color: var(--os-color-text-muted); }
.bs__price { margin: 0 0 var(--os-space-xs); display: flex; align-items: baseline; gap: 4px; font-family: var(--os-font-heading); font-weight: var(--os-font-weight-heading); color: var(--os-color-accent); line-height: 1; }
.bs__cur, .bs__num { font-size: var(--os-type-display-font-size); }
.bs__per { margin-left: var(--os-space-xs); font-family: var(--os-font-label); font-weight: 400; font-size: var(--os-type-small-font-size); color: var(--os-color-text-muted); }
.bs__blurb { margin: 0; font-size: var(--os-type-lead-font-size); line-height: var(--os-type-lead-line-height); color: var(--os-color-text); }
.bs__foot { margin-top: var(--os-space-xl); display: flex; flex-wrap: wrap; align-items: center; gap: var(--os-space-md) var(--os-space-lg); }
.bs__note { margin: 0; max-width: 34em; font-family: var(--os-font-label); font-size: var(--os-type-small-font-size); line-height: 1.6; color: var(--os-color-text-muted); }
.bs--js .bs__card { opacity: 0; transform: translateY(48px) rotate(1.5deg); }
.bs--js.is-in .bs__card { opacity: 1; transform: none; transition: opacity 0.5s ease-out, transform 0.6s var(--os-motion-ease, ease-out); transition-delay: calc(var(--i, 0) * 0.14s); }
.bs--js .bs__dot { transform: scale(0); }
.bs--js.is-in .bs__dot { transform: scale(1); transition: transform 0.3s ease-out; transition-delay: calc(0.4s + var(--i, 0) * 0.14s + var(--j, 0) * 0.08s); }
@media (min-width: 768px) { .bs__grid { grid-template-columns: repeat(3, 1fr); gap: var(--os-space-lg); } .bs__card { padding: var(--os-space-xl) var(--os-space-lg); } .bs__card:nth-child(2) { margin-top: var(--os-space-md); } .bs__card:nth-child(3) { margin-top: var(--os-space-lg); } }
@media (prefers-reduced-motion: reduce) { .bs__card, .bs__dot { transition: none !important; } }

js:
const bs = root.querySelector('.bs');
const cards = Array.prototype.slice.call(root.querySelectorAll('[data-bs-card]'));
if (!bs || cards.length === 0) return;
cards.forEach((card) => {
  const holder = card.querySelector('[data-bs-dots]');
  const n = parseInt(holder.getAttribute('data-bs-dots'), 10) || 0;
  for (let k = 0; k < n; k++) {
    const d = document.createElement('span');
    d.className = 'bs__dot';
    d.style.setProperty('--j', String(k));
    holder.appendChild(d);
  }
});
if (ctx.reducedMotion) return;
cards.forEach((card, i) => { card.style.setProperty('--i', String(i)); card.querySelectorAll('.bs__dot').forEach((d) => { d.style.setProperty('--i', String(i)); }); });
const nums = cards.map((card) => card.querySelector('[data-bs-num]'));
const finals = nums.map((el) => parseInt(el.textContent, 10) || 0);
bs.classList.add('bs--js');
nums.forEach((el) => { el.textContent = '0'; });
const run = () => {
  const start = performance.now();
  const step = (now) => {
    const t = Math.min(1, (now - start) / 1100);
    const e = 1 - Math.pow(1 - t, 3);
    nums.forEach((el, i) => { el.textContent = String(Math.round(finals[i] * e)); });
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
};
const io = new IntersectionObserver((entries) => {
  if (entries[0].isIntersecting) {
    bs.classList.add('is-in');
    run();
    io.disconnect();
  }
}, { threshold: 0.2 });
io.observe(bs.querySelector('.bs__grid'));
